ST.xhtml:
// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESET FRONT
ResetEdge(CLK := Reset);

IF ResetEdge.Q THEN
    DriveFaultLatching := FALSE;
END_IF;

IF DriveStatusWord.4 THEN
    DriveFaultLatching := TRUE;
END_IF;

instCauses[0].Active   := Brake.Fault.Error;
instCauses[0].Latching := FALSE;
instCauses[0].Texte    := 'Defaut sequence ou retour frein translation';

instCauses[3].Active   := DriveFaultLatching;
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Defaut variateur translation AC600';

// REX MES 2026-09-04 (trace Suivi_TranslationM3bug_20260904_27) : ce test se declenchait
// INSTANTANEMENT a chaque arrivee NOMINALE sur le FdC (CommandedTremie ET LimitSwitchTremie
// sont vrais des le 1er scan d'une arrivee normale, avant meme que la decel soit terminee)
// -> Fault.Error pulse -> §6 force BrakeReleaseRequest:=FALSE en ecrasant Brake.BrakeCmd
// pendant que FB_Brake pense toujours commander l'ouverture (son propre MovementRequested
// reste vrai le temps du coast ~600ms) -> incoherence commande/retour frein -> latch
// definitif dans FB_Brake. On ne fault desormais que sur un DEPASSEMENT REEL : encore
// commande vers le FdC, sur le FdC, ET reellement en train de tourner (pas juste en decel),
// soutenu 1.5s (meme garde que FB_Safety_Translation Cause 6).
OverrunLimitSwitch := NOT BypassLimitSwitch
    AND ((CommandedTremie AND LimitSwitchTremie) OR (CommandedMaintenance AND LimitSwitchMaintenance))
    AND (ABS(DriveActualFreqHz) > 0.5);
TonLimitSwitchOverrun(IN := OverrunLimitSwitch, PT := T#1S500MS);
instCauses[6].Active := TonLimitSwitchOverrun.Q;
instCauses[6].Latching := FALSE;
instCauses[6].Texte    := 'Limite extreme translation atteinte';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    SpeedRamp(Target := 0.0, AccelRate := 0.0, DecelRate := 100000.0, CycleTimeS := 1.0);
    Brake(Enable := FALSE);
    RequestedDriveControlWord := 0;
    RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
    BrakeCommandOpenConfirmed := FALSE;
    BrakeContactorCheck.Command := FALSE;
    BrakeContactorCheck.Feedback := BrakeFeedback;
    CommandedTremie := FALSE;
    CommandedMaintenance := FALSE;
    DirectionChangePending := FALSE;
    ArrivalLock := FALSE;
    ArrivalWasTremie := FALSE;
    ArrivalWasMaintenance := FALSE;
    TargetReached := FALSE;
    DirectionChangeDelay(IN := FALSE);
    CaptorDebounceTon(IN := FALSE);
    TonBrakeRealFreqTimeout(IN := FALSE);
    Ready := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Premier scan et temps de cycle"}
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    CommandedTremie := FALSE;
    CommandedMaintenance := FALSE;
END_IF;

CycleTimeCalc();
{endregion}

{region "§4 Arrivée sur cible et interlock direction"}
CaptorDebounceTon(IN := PositionSensorTarget, PT := Cfg.CaptorDebounce);
TargetReached := CaptorDebounceTon.Q;
ArrivalEdge(CLK := TargetReached);

IF ArrivalEdge.Q THEN
    ArrivalLock := TRUE;
    ArrivalWasTremie := CommandedTremie;
    ArrivalWasMaintenance := CommandedMaintenance;
END_IF;

IF ArrivalLock AND ((ReqTremie AND NOT ArrivalWasTremie) OR (ReqMaintenance AND NOT ArrivalWasMaintenance)) THEN
    ArrivalLock := FALSE;
END_IF;

DirectionChangeDelay(
    IN := (ReqTremie OR ReqMaintenance)
          AND ((ReqTremie AND NOT CommandedTremie) OR (ReqMaintenance AND NOT CommandedMaintenance))
          AND (ABS(SpeedRamp.Current) <= 0.1)
          AND (ABS(DriveActualFreqHz) <= 0.5),
    PT := Cfg.DirectionInterlockDelay
);

IF NOT (CommandedTremie OR CommandedMaintenance) AND (ReqTremie OR ReqMaintenance) THEN
    CommandedTremie := ReqTremie;
    CommandedMaintenance := ReqMaintenance;
    DirectionChangePending := FALSE;
ELSIF DirectionChangeDelay.Q THEN
    CommandedTremie := ReqTremie;
    CommandedMaintenance := ReqMaintenance;
    DirectionChangePending := FALSE;
ELSIF (ReqTremie OR ReqMaintenance)
      AND ((ReqTremie AND NOT CommandedTremie) OR (ReqMaintenance AND NOT CommandedMaintenance)) THEN
    DirectionChangePending := TRUE;
ELSE
    DirectionChangePending := FALSE;
END_IF;

IF NOT (ReqTremie OR ReqMaintenance) THEN
    CommandedTremie := FALSE;
    CommandedMaintenance := FALSE;
    DirectionChangePending := FALSE;
END_IF;
{endregion}

{region "§4bis Permis directionnels et EffectiveSafeStop"}
// 🛡️ 4bis. GATE DE SENS (permis directionnels SAFETY) — modèle treuils FB_Winch
// RampStopActive = SafeStop OR demande vers un sens non permis. Bloque la RAMPE
// (arrêt réel) vers un sens non autorisé sans fabriquer de sens numérique.
// Consommé dans la gate de rampe (§5) et le choix de décélération.
// Le permis Maintenance représente la possibilité de rejoindre P1/maintenance physique ;
// l'interdiction d'accès à la zone Maintenance est gérée séparément par la cible P1 et sa
// coupure dure, sans couper le déplacement légal jusqu'à P1.
EffectiveSafeStop := SafeStop
                      OR (ReqTremie AND NOT EffectivePermitM3_Tremie)
                      OR (ReqMaintenance AND NOT EffectivePermitM3_Maintenance)
                      OR (ReqTremie AND ReqMaintenance);
{endregion}

{region "§5 Consigne et rampe de vitesse"}
IF DirectionChangePending OR NOT (ReqTremie OR ReqMaintenance) OR ArrivalLock OR EffectiveSafeStop OR NOT RunRequest THEN
    RampTargetPct := 0.0;
ELSE
    RampTargetPct := LIMIT(0.0, SpeedTgt_Pct, 100.0);
END_IF;

SpeedRamp(
    Target := RampTargetPct,
    AccelRate := Cfg.CfgRampAccelRate,
    DecelRate := SEL(EffectiveSafeStop, Cfg.CfgRampDecelNormalRate, Cfg.CfgRampDecelFastRate),
    CycleTimeS := CycleTimeCalc.CycleTimeS
);
{endregion}

{region "§6 Commande variateur et frein"}
TonBrakeRealFreqTimeout(
    IN := (RampTargetPct <= 0.1) AND (ABS(SpeedRamp.Current) <= 0.1),
    PT := T#2S
);

MovementRequested := (ABS(SpeedRamp.Current) > 0.1)
                  OR ((ABS(DriveActualFreqHz) > 0.5) AND NOT TonBrakeRealFreqTimeout.Q);

Brake(
    Enable := Enable,
    Reset := Reset,
    MovementRequested := MovementRequested,
    ContactorFeedback := BrakeFeedback,
    BypassContactorCheck := BypassContactorCheck,
    DelayContactClose := Cfg.BrakeDelayContactClose,
    DelayMagnetise := Cfg.BrakeDelayMagnetise,
    DelayMotorDecel := Cfg.BrakeDelayMotorDecel,
    FeedbackTimeout := Cfg.BrakeFeedbackTimeout
);

BrakeReleaseRequest := Brake.BrakeCmd;
BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
BrakeContactorCheck := Brake.ContactorCheck;

PhysicalTremie := CommandedTremie;
PhysicalMaintenance := CommandedMaintenance;
IF InvertDriveDirection THEN
    PhysicalTremie := CommandedMaintenance;
    PhysicalMaintenance := CommandedTremie;
END_IF;

IF PhysicalTremie AND Brake.BrakeCmd THEN
    RequestedDriveControlWord := 1; // FWD
ELSIF PhysicalMaintenance AND Brake.BrakeCmd THEN
    RequestedDriveControlWord := 2; // REV
ELSE
    RequestedDriveControlWord := 0;
END_IF;

RequestedDriveFreqHz := (SpeedRamp.Current / 100.0) * Cfg.DriveFreqScaleMaxHz;

// Ralentissements d'approche
IF CommandedTremie AND SlowdownSensorTremie THEN
    RequestedDriveFreqHz := MIN(RequestedDriveFreqHz, Cfg.ApproachSpeedTremieHz);
ELSIF CommandedMaintenance AND SlowdownSensorMaintenance THEN
    RequestedDriveFreqHz := MIN(RequestedDriveFreqHz, Cfg.ApproachSpeedMaintenanceHz);
ELSIF CommandedMaintenance AND SlowdownSensorP1 THEN
    RequestedDriveFreqHz := MIN(RequestedDriveFreqHz, Cfg.ApproachSpeedP1Hz);
END_IF;

IF Fault.Error THEN
    RequestedDriveControlWord := 0;
    RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
END_IF;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Fronts"}
// 🔑 1. FRONTS
ResetEdge(CLK := Reset);
BypassEdge(CLK := BypassContactorCheck);

// Acquittement des drapeaux contacteur
IF ResetEdge.Q OR BypassContactorCheck THEN
    ContactorIncoherentError := FALSE;
    ContactorCheck.StuckClosed := FALSE;
    ContactorCheck.StuckOpen   := FALSE;
END_IF;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE — pas d'Enable = frein collé (sécurité positive), aucune temporisation en cours
IF NOT Enable THEN
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    TonFeedback(IN := FALSE, PT := FeedbackTimeout);
    BrakeCmd := FALSE;
    Ready := FALSE;
    ContactorCheck.Command := FALSE;          // 📊 Neutralisation : miroir de BrakeCmd := FALSE
    ContactorCheck.Feedback := ContactorFeedback; // 📊 Neutralisation : miroir entrée physique
    BrakeCommandOpenConfirmed := FALSE;       // 🛡️ Fail-Safe : frein commandé fermé hors Enable

    // Évaluation du socle de défaut sous neutralisation (permet acquittement Reset hors Enable)
    instCauses[0].Active   := FALSE;
    instCauses[0].Latching := TRUE;
    instCauses[0].Texte    := 'Incoherence retour contacteur frein';
    instFault(Enable := FALSE, Reset := Reset, Causes := instCauses);
    Fault := instFault.Fault;
    RETURN;
END_IF;
{endregion}

{region "§3 Séquence temporisée"}
// 🛠️ 3. SÉQUENCE TEMPORISÉE (démarrage vs arrêt)
IF MovementRequested THEN
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    TonMagnetise(IN := TRUE, PT := DelayMagnetise + DelayContactClose);
    IF TonMagnetise.Q THEN
        BrakeCmd := TRUE;              // ✅ Contacteur + magnétisation acquis → relâche
    ELSE
        BrakeCmd := FALSE;             // ⏳ Encore collé pendant la magnétisation
    END_IF;
ELSE
    // Sécurité positive : fermeture immédiate du frein (collé) dès que les contacteurs de sens s'ouvrent
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;                 // Fermeture immédiate
END_IF;
{endregion}

{region "§4 Double vérification contacteur"}
// 🔍 4. DOUBLE VÉRIFICATION RETOUR CONTACTEUR (ST_ContactorCheck)
ContactorCheck.Command := BrakeCmd;
ContactorCheck.Feedback := ContactorFeedback;

// ContactorFeedback est dans le MÊME sens que BrakeCmd (TRUE = relâché = frein ouvert).
TonFeedback(IN := (BrakeCmd <> ContactorFeedback), PT := FeedbackTimeout);
IF NOT BypassContactorCheck THEN
    IF TonFeedback.Q THEN
        ContactorCheck.StuckClosed := (BrakeCmd AND NOT ContactorFeedback);
        ContactorCheck.StuckOpen   := (NOT BrakeCmd AND ContactorFeedback);
        ContactorIncoherentError   := TRUE;
    END_IF;
END_IF;
{endregion}

{region "§5 Causes & Socle Défaut"}
// 🚨 5. SOCLE DÉFAUT & SORTIE SÛRE
instCauses[0].Active   := NOT BypassContactorCheck AND (ContactorCheck.StuckClosed OR ContactorCheck.StuckOpen OR (TonFeedback.Q AND (BrakeCmd <> ContactorFeedback)));
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Incoherence retour contacteur frein';

instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

Ready := Enable AND NOT Fault.Latched;

// Sortie sûre immédiate
IF Fault.Error OR Fault.Latched THEN
    BrakeCmd := FALSE;
END_IF;
{endregion}

{region "§6 Confirmation ouverture"}
// 📤 6. CONFIRMATION OUVERTURE FREIN
IF BypassContactorCheck THEN
    BrakeCommandOpenConfirmed := BrakeCmd;
ELSE
    BrakeCommandOpenConfirmed := ContactorFeedback AND NOT Fault.Latched;  (* TRUE = frein ouvert = desserrage confirmé *)
END_IF;
{endregion}

{region "§1 Acquisition temps"}
// 1. ACQUISITION DU TEMPS SYSTÈME
TimeCurrent := TIME();
{endregion}

{region "§2 Initialisation"}
// 2. INITIALISATION UNIQUE AU PREMIER CYCLE
IF NOT InitDone THEN
    TimeLast := TimeCurrent;
    InitDone := TRUE;
    CycleTimeS := DefaultValueS;
    RETURN;
END_IF;
{endregion}

{region "§3 Calcul delta"}
// 3. CALCUL DU DELTA EN MILLISECONDES
DeltaTimeMs := TIME_TO_UDINT(TimeCurrent - TimeLast);
{endregion}

{region "§4 Conversion, secours et bornage"}
// 4. CONVERSION EN SECONDES, AVEC DOUBLE BORNAGE DU DELTA
//
// TIME() est un compteur systeme 32 bits en millisecondes depuis le demarrage de
// l'automate. Il n'est PAS absolu : il reboucle a 0 tous les 2^32 ms (~49,7 jours).
// La soustraction TimeCurrent - TimeLast est modulo 2^32 : au passage du rebouclage,
// tant que l'ecart reel entre deux scans reste < 49,7 j (toujours vrai a 10 ms),
// DeltaTimeMs reste correct. Le rebouclage seul n'est donc pas le risque principal.
//
// Le vrai risque est un DeltaTimeMs REELLEMENT > CST_MaxCycleDeltaMs : reprise apres
// un online-change, sortie d'un point d'arret / pas-a-pas debug, ou fenetre du
// rebouclage TIME(). Le chien de garde tache (200 ms, sensibilite 1) borne deja les
// gels en fonctionnement ; ce plafond couvre les cas hors surveillance.
// Un dt aberrant publie tel quel donnerait un CycleTimeS enorme, propage en un seul
// scan dans les rampes de vitesse et les integrateurs de position/frein -> saut
// physique. Fail-safe : hors de la plage nominale (0 < dt <= plafond), on publie la
// valeur de secours DefaultValueS au lieu de l'artefact. Pas de redemarrage auto.
//
// Borne basse dt = 0 (anti-zero, ex. premier appel du scan) et borne haute
// dt > CST_MaxCycleDeltaMs (anti-artefact) partagent la meme branche de secours.
IF (DeltaTimeMs > 0) AND (DeltaTimeMs <= CST_MaxCycleDeltaMs) THEN
    CycleTimeS := UDINT_TO_REAL(DeltaTimeMs) / 1000.0;
ELSE
    CycleTimeS := DefaultValueS;
END_IF;
{endregion}

{region "§5 Archivage"}
// 5. ARCHIVAGE POUR LE PROCHAIN CYCLE
TimeLast := TimeCurrent;
{endregion}

{region "§1 Reset (front, toujours effectif)"}
// Front Reset : efface tous les latches. Jamais conditionné, agit même Enable=FALSE (§9).
Ready := Enable;
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    FOR i := 0 TO 15 DO Latch[i] := FALSE; END_FOR;
END_IF;
{endregion}

{region "§2 Vue LIVE — Error / ErrorId"}
// Bitfield des causes présentes MAINTENANT. Retombe seule à 0 quand les causes disparaissent.
// Non évaluée si Enable=FALSE (pas de lecture de cause hors autorisation).
Fault.ErrorId := 0;
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active THEN
            Fault.ErrorId := Fault.ErrorId OR SHL(WORD#1, INT_TO_DWORD(i));
        END_IF;
    END_FOR;
END_IF;
Fault.Error := (Fault.ErrorId <> 0);
{endregion}

{region "§3 Armement des latches (causes à acquitter)"}
// Une cause Active ET Latching arme son bit ; le bit reste jusqu'au front Reset (§1),
// même si la cause disparaît. Réapparition => ré-armement (ré-alarme).
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active AND Causes[i].Latching THEN
            Latch[i] := TRUE;
        END_IF;
    END_FOR;
END_IF;
{endregion}

{region "§4 Vue LATCHÉE — Latched / LatchedId"}
// Toujours publiée, y compris Enable=FALSE : un défaut non acquitté reste visible.
Fault.LatchedId := 0;
FOR i := 0 TO 15 DO
    IF Latch[i] THEN
        Fault.LatchedId := Fault.LatchedId OR SHL(WORD#1, INT_TO_DWORD(i));
    END_IF;
END_FOR;
Fault.Latched := (Fault.LatchedId <> 0);
{endregion}

// Détection du comportement (Accélération vs Décélération)
// Classification par CÔTÉ DE ZÉRO + sens de déplacement, plus par signe brut de Target seul
// (robuste à une traversée de zéro rapide).
// 🛡️ Garde-fou : la rampe ne sort jamais de la plage normalisée ±100 %.
TargetLimited := LIMIT(-100.0, Target, 100.0);
Current := LIMIT(-100.0, Current, 100.0);

IF (Current >= 0.0 AND TargetLimited >= Current) OR (Current <= 0.0 AND TargetLimited <= Current) THEN
    StepX := AccelRate * CycleTimeS; // S'éloigne du zéro (reste du même côté, va plus loin)
ELSE
    StepX := DecelRate * CycleTimeS; // Retourne vers zéro, ou le traverse vers l'autre signe
END_IF;

// Application de la rampe
IF Current < TargetLimited THEN
    Current := Current + StepX;
    IF Current > TargetLimited THEN Current := TargetLimited; END_IF;
ELSIF Current > TargetLimited THEN
    Current := Current - StepX;
    IF Current < TargetLimited THEN Current := TargetLimited; END_IF;
END_IF;

// 🛡️ Limitation finale : même une valeur d'état déjà corrompue reste bornée.
Current := LIMIT(-100.0, Current, 100.0);
